-- RayTrace syscall catalog, version 2.
-- One row per Linux syscall name gVisor knows, in every group: files, network,
-- process, identity, memory, IPC, time and other. `capture` is RayTrace's own
-- decision for each row, and it is carried out: setup.py builds gVisor's trace
-- configuration from it, and engine.py names raw events with syscall_numbers.
-- Loading this file into a database enables nothing by itself.
-- Standalone SQLite database; do not add to application migrations.
-- Names are Linux syscall names, not shell commands or libc aliases. Numbers
-- differ by architecture and are in syscall_numbers.
-- Re-import updates catalog-owned rows without replacing/deleting other rows.
-- syscall_numbers and syscall_coverage are generated from gVisor's source by
-- catalog_numbers.py and are replaced whole.
-- Event outcome and confirmed effect must remain separate from default impact.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;

CREATE TABLE IF NOT EXISTS syscall_impact_levels (
    level INTEGER PRIMARY KEY CHECK (level BETWEEN 0 AND 3),
    label TEXT NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS syscall_groups (
    group_id TEXT PRIMARY KEY,
    label TEXT NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS syscall_categories (
    category_id TEXT PRIMARY KEY,
    label TEXT NOT NULL,
    description TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS syscall_catalog (
    syscall_name TEXT PRIMARY KEY,
    description TEXT NOT NULL CHECK (length(trim(description)) > 0),
    group_id TEXT NOT NULL REFERENCES syscall_groups(group_id),
    category_id TEXT NOT NULL REFERENCES syscall_categories(category_id),
    default_impact_level INTEGER REFERENCES syscall_impact_levels(level)
        CHECK (default_impact_level IS NULL OR default_impact_level BETWEEN 0 AND 3),
    classification_rule TEXT NOT NULL CHECK (length(trim(classification_rule)) > 0),
    required_evidence TEXT NOT NULL CHECK (length(trim(required_evidence)) > 0),
    interpretation_notes TEXT NOT NULL CHECK (length(trim(interpretation_notes)) > 0),
    -- yes:     its gVisor trace point is subscribed.
    -- watcher: only its raw exit point is subscribed (who, when, refused or
    --          not); gVisor does not decode its path, so the host's file
    --          watcher supplies the name.
    -- sentry:  seen through gVisor's own process points (clone, exec, exit),
    --          whatever syscall caused them.
    -- no:      not captured.
    capture TEXT NOT NULL DEFAULT 'no' CHECK (capture IN ('yes', 'watcher', 'sentry', 'no')),
    -- Optional fields to ask gVisor for on that point, a JSON list.
    capture_fields TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(capture_fields) AND json_type(capture_fields) = 'array'),
    -- The engine.py rule that reads the event; null when nothing does.
    effect_rule TEXT,
    catalog_version INTEGER NOT NULL DEFAULT 2 CHECK (catalog_version = 2)
);

-- Generated. A syscall number names a different call on each architecture.
-- `support` is gVisor's own: unsupported calls fail inside the sandbox.
CREATE TABLE IF NOT EXISTS syscall_numbers (
    arch TEXT NOT NULL CHECK (arch IN ('x86_64', 'aarch64')),
    sysno INTEGER NOT NULL CHECK (sysno >= 0),
    syscall_name TEXT NOT NULL REFERENCES syscall_catalog(syscall_name),
    support TEXT NOT NULL CHECK (support IN ('supported', 'partial', 'unsupported')),
    PRIMARY KEY (arch, sysno),
    UNIQUE (arch, syscall_name)
);

-- Generated, one row per syscall of one gVisor release. `point` is the typed
-- trace point (decoded paths, flags, addresses); null means gVisor reports the
-- call by number and six integers only. `observed` is what a live test saw
-- (spike_points.py): 1 arrived, 0 subscribed and silent, null not tested.
CREATE TABLE IF NOT EXISTS syscall_coverage (
    gvisor_release TEXT NOT NULL,
    syscall_name TEXT NOT NULL REFERENCES syscall_catalog(syscall_name),
    point TEXT,
    optional_fields TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(optional_fields) AND json_type(optional_fields) = 'array'),
    observed INTEGER CHECK (observed IS NULL OR observed IN (0, 1)),
    observed_fields TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(observed_fields) AND json_type(observed_fields) = 'array'),
    PRIMARY KEY (gvisor_release, syscall_name)
);

INSERT INTO syscall_impact_levels (level, label, description) VALUES
(0, 'Observe', 'Read or inspect without an explicit mutation request; sensitive reads and incidental atime updates are possible. Impact is not maliciousness.'),
(1, 'Create', 'Add a filesystem entry without replacing existing data. Impact is not maliciousness.'),
(2, 'Modify', 'Change existing file contents, metadata, layout or location. Impact is not maliciousness.'),
(3, 'Remove/replace', 'Remove a filesystem entry or replace an existing destination. Impact is not maliciousness.')
ON CONFLICT(level) DO UPDATE SET label=excluded.label, description=excluded.description;

INSERT INTO syscall_groups (group_id, label, description) VALUES
('files', 'Files', 'Files, directories, mounts and the descriptors that refer to them.'),
('network', 'Network', 'Sockets: connecting, listening and transferring data.'),
('process', 'Process', 'Starting, replacing, signalling, controlling and inspecting processes and threads.'),
('identity', 'Identity', 'User and group identity and capabilities.'),
('memory', 'Memory', 'Address space management.'),
('ipc', 'IPC', 'Pipes, shared memory, semaphores, message queues and locks between processes.'),
('time', 'Time', 'Clocks, timers and sleeping.'),
('other', 'Other', 'Waiting for events, system information and administration.')
ON CONFLICT(group_id) DO UPDATE SET label=excluded.label, description=excluded.description;

