('metadata_change', 'Metadata change', 'Change file permissions, ownership, attributes or timestamps.'),
('link', 'Create link', 'Add a hard link or symbolic link.'),
('mapping', 'Memory mapping', 'Establish or manage potentially file-backed memory mappings.'),
('descriptor_bookkeeping', 'Descriptor / path bookkeeping', 'Track descriptor state, path context or synchronization.'),
('mount', 'Mount', 'Mount, unmount or re-root filesystems.'),
('file_watch', 'Watch files', 'Ask to be told of changes to files.'),
('create_special', 'Create special file', 'Add a device, FIFO or socket node.'),
('async_io', 'Asynchronous I/O', 'Queue file or socket operations that complete later, outside the ordinary read and write calls.'),
('network_connect', 'Connect', 'Open a connection to a remote address.'),
('network_listen', 'Listen / accept', 'Bind a local address and take incoming connections.'),
('network_transfer', 'Send / receive', 'Send or receive data on a socket.'),
('network_socket', 'Socket setup', 'Create, configure, inspect or shut down a socket.'),
('process_spawn', 'Start process', 'Create a process or thread.'),
('process_exec', 'Run program', 'Replace the running program with another.'),
('process_exit', 'Exit', 'End a thread or process.'),
('process_control', 'Process control', 'Wait for, trace, limit, schedule or isolate a process.'),
('process_info', 'Process information', 'Read process identifiers, limits, usage or scheduling.'),
('signal', 'Signal', 'Send, wait for or configure signals.'),
('identity_change', 'Change identity', 'Change user or group identity or capabilities.'),
('identity_info', 'Identity information', 'Read user or group identity or capabilities.'),
('memory', 'Memory', 'Manage the address space apart from file mappings.'),
('ipc', 'IPC', 'Communicate or synchronize between processes.'),
('time', 'Time', 'Read or set clocks, sleep, or use timers.'),
('event_wait', 'Wait for events', 'Wait for descriptors to become ready.'),
('system', 'System', 'System information and administration.')
ON CONFLICT(category_id) DO UPDATE SET label=excluded.label, description=excluded.description;

