('splice', 'Transfers data between descriptors with at least one pipe endpoint.', 'copy', NULL, 'copy_effect', 'source/destination fd identities and types, offsets, requested and returned bytes, flags, errno, destination creation evidence', 'Require a file destination before assigning filesystem impact. Positive transferred bytes to an existing file are level 2; confirmed creation is a separate level 1 event. Pipe/socket destinations are not file edits. Do not infer secret exfiltration.'),
('fallocate', 'Allocates or changes file ranges according to mode flags.', 'resize', NULL, 'allocation_effect', 'fd target identity/type, mode flags, offset, length, return value, errno', 'Decoded successful allocation/range changes on files are level 2; punch-hole, zero-range, collapse-range and insert-range may alter data. Allocation alone does not prove changed contents.'),
('ioctl', 'Performs a command-specific operation on a descriptor, which may affect file data or metadata.', 'metadata_change', NULL, 'ioctl_effect', 'fd target identity/type, decoded ioctl command and relevant arguments, return value, errno', 'No generic impact. Decode supported commands: file clone/range clone to an existing destination is level 2, file attribute changes are level 2, inspection is level 0. Unknown commands remain unclassified.'),
('mmap', 'Maps a file or anonymous memory into the process address space.', 'mapping', NULL, 'mapping_effect', 'file identity and fd where available, address/range, protections, mapping flags, tracked mapping identity, return value, errno', 'A readable file mapping indicates possible access, not confirmed reads; a shared writable mapping indicates possible modification, not actual writes. Mapping/protection/sync/unmap calls alone do not confirm changed bytes; leave impact unresolved without additional evidence.'),
('mprotect', 'Changes access protections for a mapped memory range.', 'mapping', NULL, 'mapping_effect', 'file identity and fd where available, address/range, protections, mapping flags, tracked mapping identity, return value, errno', 'A readable file mapping indicates possible access, not confirmed reads; a shared writable mapping indicates possible modification, not actual writes. Mapping/protection/sync/unmap calls alone do not confirm changed bytes; leave impact unresolved without additional evidence.'),
('msync', 'Requests synchronization of a mapped file range with its backing storage.', 'mapping', NULL, 'mapping_effect', 'file identity and fd where available, address/range, protections, mapping flags, tracked mapping identity, return value, errno', 'A readable file mapping indicates possible access, not confirmed reads; a shared writable mapping indicates possible modification, not actual writes. Mapping/protection/sync/unmap calls alone do not confirm changed bytes; leave impact unresolved without additional evidence.'),
('munmap', 'Removes mappings from a process address range.', 'mapping', NULL, 'mapping_effect', 'file identity and fd where available, address/range, protections, mapping flags, tracked mapping identity, return value, errno', 'A readable file mapping indicates possible access, not confirmed reads; a shared writable mapping indicates possible modification, not actual writes. Mapping/protection/sync/unmap calls alone do not confirm changed bytes; leave impact unresolved without additional evidence.'),
('close', 'Closes a file descriptor.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('close_range', 'Closes a range of descriptors or marks them close-on-exec according to flags.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('dup', 'Duplicates a descriptor into the lowest available descriptor number.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('dup2', 'Duplicates a descriptor into a specified descriptor number.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('dup3', 'Duplicates a descriptor into a specified number with explicit flags.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('fcntl', 'Performs descriptor control operations such as duplication or flag changes.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('lseek', 'Changes the file offset associated with a descriptor.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('chdir', 'Changes the working directory used to interpret relative paths.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('fchdir', 'Changes the working directory using a directory descriptor.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('fsync', 'Requests synchronization of file data and metadata to storage.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.'),
('fdatasync', 'Requests synchronization of file data and necessary metadata to storage.', 'descriptor_bookkeeping', NULL, 'bookkeeping', 'process identity, relevant descriptors/paths, command or flags, return value, errno', 'No direct filesystem impact level. Retain as context; closing or syncing can flush earlier writes but is not a new confirmed content edit. fcntl requires command decoding and is not automatically a file mutation.')
) WHERE true
ON CONFLICT(syscall_name) DO UPDATE SET
    description=excluded.description,
    group_id=excluded.group_id,
    category_id=excluded.category_id,
    default_impact_level=excluded.default_impact_level,
    classification_rule=excluded.classification_rule,
    required_evidence=excluded.required_evidence,
    interpretation_notes=excluded.interpretation_notes,
    capture=excluded.capture,
    capture_fields=excluded.capture_fields,
    effect_rule=excluded.effect_rule,
    catalog_version=excluded.catalog_version;

-- Network, identity and process calls RayTrace reads, with their rules.
INSERT INTO syscall_catalog
    (syscall_name, description, group_id, category_id, default_impact_level,
     classification_rule, required_evidence, interpretation_notes,
     capture, capture_fields, effect_rule, catalog_version)
VALUES
('connect', 'Connects a socket to a remote address.', 'network', 'network_connect', NULL, 'connect_effect', 'socket descriptor, decoded address (family, IP address, port), return value, errno', 'Success on a stream socket establishes a connection; on a datagram socket it only sets the default peer. EINPROGRESS on a non-blocking socket is an attempt whose outcome this call does not report. The address is an IP address, never a host name: names come from DNS evidence and are a best match. A destination the sandbox firewall rejects is a refused attempt. No payload is captured.', 'yes', '[]', 'connect', 2),
('listen', 'Marks a socket as accepting incoming connections.', 'network', 'network_listen', NULL, 'listen_effect', 'socket descriptor, bound address, backlog, return value, errno', 'Success means the process started accepting connections on the bound address. Nothing outside the sandbox network is routed to it, so this is context, not exposure.', 'yes', '[]', 'listen', 2),
('setuid', 'Sets the user ID of the calling process.', 'identity', 'identity_change', NULL, 'identity_effect', 'requested IDs, return value, errno', 'Success changes the identity the process acts as. The sandbox runs as one unprivileged user with no capabilities and no-new-privileges, so a successful change away from that user is unexpected; a failure is an attempt.', 'yes', '[]', 'identity', 2),
('setgid', 'Sets the group ID of the calling process.', 'identity', 'identity_change', NULL, 'identity_effect', 'requested IDs, return value, errno', 'Success changes the identity the process acts as. The sandbox runs as one unprivileged user with no capabilities and no-new-privileges, so a successful change away from that user is unexpected; a failure is an attempt.', 'yes', '[]', 'identity', 2),
('setresuid', 'Sets the real, effective and saved user IDs.', 'identity', 'identity_change', NULL, 'identity_effect', 'requested IDs, return value, errno', 'Success changes the identity the process acts as. The sandbox runs as one unprivileged user with no capabilities and no-new-privileges, so a successful change away from that user is unexpected; a failure is an attempt.', 'yes', '[]', 'identity', 2),
('setresgid', 'Sets the real, effective and saved group IDs.', 'identity', 'identity_change', NULL, 'identity_effect', 'requested IDs, return value, errno', 'Success changes the identity the process acts as. The sandbox runs as one unprivileged user with no capabilities and no-new-privileges, so a successful change away from that user is unexpected; a failure is an attempt.', 'yes', '[]', 'identity', 2),
('clone', 'Creates a process or thread.', 'process', 'process_spawn', NULL, 'process_lifecycle', 'gVisor process points: new task identity, parent, start time', 'Seen through gVisor''s clone point, which reports every new task whichever syscall created it. A new task is not a new program: that is an exec.', 'sentry', '[]', 'process', 2),
('clone3', 'Creates a process or thread, with an extensible argument.', 'process', 'process_spawn', NULL, 'process_lifecycle', 'gVisor process points: new task identity, parent, start time', 'Seen through gVisor''s clone point, which reports every new task whichever syscall created it. A new task is not a new program: that is an exec.', 'sentry', '[]', 'process', 2),
('fork', 'Creates a child process.', 'process', 'process_spawn', NULL, 'process_lifecycle', 'gVisor process points: new task identity, parent, start time', 'Seen through gVisor''s clone point, which reports every new task whichever syscall created it. A new task is not a new program: that is an exec.', 'sentry', '[]', 'process', 2),
('vfork', 'Creates a child process and suspends the parent until it execs or exits.', 'process', 'process_spawn', NULL, 'process_lifecycle', 'gVisor process points: new task identity, parent, start time', 'Seen through gVisor''s clone point, which reports every new task whichever syscall created it. A new task is not a new program: that is an exec.', 'sentry', '[]', 'process', 2),
('execve', 'Replaces the running program with another.', 'process', 'process_exec', NULL, 'process_lifecycle', 'executable path, arguments, the two RAYTRACE_ markers from the environment, return value, errno', 'gVisor''s exec point confirms a program started; the syscall point also reports attempts that failed. A zero result on the syscall point is not treated as success. Arguments can hold secrets. Of the environment only the two RAYTRACE_ markers are kept.', 'sentry', '["envv"]', 'process', 2),
('execveat', 'Replaces the running program with one named relative to a directory descriptor.', 'process', 'process_exec', NULL, 'process_lifecycle', 'executable path, arguments, the two RAYTRACE_ markers from the environment, return value, errno', 'gVisor''s exec point confirms a program started; the syscall point also reports attempts that failed. A zero result on the syscall point is not treated as success. Arguments can hold secrets. Of the environment only the two RAYTRACE_ markers are kept.', 'sentry', '["envv"]', 'process', 2),
('exit', 'Ends the calling thread.', 'process', 'process_exit', NULL, 'process_lifecycle', 'gVisor process points: exit status or signal', 'Seen through gVisor''s exit points. An exit code of 0 means the program did not report a failure, not that it did what its name suggests.', 'sentry', '[]', 'process', 2),
('exit_group', 'Ends every thread of the calling process.', 'process', 'process_exit', NULL, 'process_lifecycle', 'gVisor process points: exit status or signal', 'Seen through gVisor''s exit points. An exit code of 0 means the program did not report a failure, not that it did what its name suggests.', 'sentry', '[]', 'process', 2)
ON CONFLICT(syscall_name) DO UPDATE SET
    description=excluded.description,
    group_id=excluded.group_id,
    category_id=excluded.category_id,
    default_impact_level=excluded.default_impact_level,
    classification_rule=excluded.classification_rule,
    required_evidence=excluded.required_evidence,
    interpretation_notes=excluded.interpretation_notes,
    capture=excluded.capture,
    capture_fields=excluded.capture_fields,
    effect_rule=excluded.effect_rule,
    catalog_version=excluded.catalog_version;

