-- What RayTrace captures of the file calls. Each row above was first set back
-- to 'no' by its own insert, so re-importing ends in the same place.
UPDATE syscall_catalog SET capture='yes', capture_fields='["fd_path"]', effect_rule='open' WHERE syscall_name IN ('openat', 'creat');
UPDATE syscall_catalog SET capture='yes', effect_rule='open' WHERE syscall_name = 'open';
UPDATE syscall_catalog SET capture='watcher', effect_rule='remove' WHERE syscall_name IN ('unlink', 'unlinkat', 'rmdir');
UPDATE syscall_catalog SET capture='watcher', effect_rule='rename' WHERE syscall_name IN ('rename', 'renameat', 'renameat2');
UPDATE syscall_catalog SET capture='watcher', effect_rule='resize' WHERE syscall_name IN ('truncate', 'ftruncate');
UPDATE syscall_catalog SET capture='watcher', effect_rule='mkdir' WHERE syscall_name IN ('mkdir', 'mkdirat');
UPDATE syscall_catalog SET capture='watcher', effect_rule='metadata' WHERE syscall_name IN ('chmod', 'fchmod', 'fchmodat');

