-- END GENERATED coverage

-- `detail` is what gVisor can tell of a call: full (a typed point), number_only
-- (the number and six integers), or none (this gVisor release has no such call).
CREATE VIEW IF NOT EXISTS syscall_catalog_readable AS
SELECT s.syscall_name, s.description, s.group_id, g.label AS group_label,
       s.category_id, c.label AS category,
       s.default_impact_level, i.label AS impact_label,
       s.classification_rule, s.required_evidence, s.interpretation_notes,
       s.capture, s.capture_fields, s.effect_rule,
       CASE WHEN v.syscall_name IS NULL THEN 'none' WHEN v.point IS NULL THEN 'number_only' ELSE 'full' END AS detail,
       v.observed, s.catalog_version
FROM syscall_catalog AS s
JOIN syscall_groups AS g ON g.group_id = s.group_id
JOIN syscall_categories AS c ON c.category_id = s.category_id
LEFT JOIN syscall_impact_levels AS i ON i.level = s.default_impact_level
LEFT JOIN syscall_coverage AS v ON v.syscall_name = s.syscall_name;

COMMIT;

-- Example: SELECT syscall_name, category, default_impact_level, capture, detail
--          FROM syscall_catalog_readable WHERE syscall_name = 'unlinkat';
-- Result: unlinkat | Delete | 3 | watcher | number_only
